<h1><?= e($report['name']) ?> · <?= e(t('Activity report')) ?></h1><p class="muted"><?= e(t('Read-only · latest 100 tasks and 30 recorded focus days. Private journals and financial records are excluded.')) ?></p><h2><?= e(t('Tasks')) ?></h2><?php if(!$report['tasks']): ?><p><?= e(t('No tasks yet.')) ?></p><?php endif; ?><ul><?php foreach($report['tasks'] as $task): ?><li><?= e($task['title']) ?> · <?= e(t($task['status'])) ?> <?= e($task['due']??'') ?></li><?php endforeach; ?></ul><h2><?= e(t('Habits')) ?></h2><ul><?php foreach($report['habits'] as $habit): ?><li><?= e($habit['title']) ?> · <?= (int)$habit['checkins'] ?> <?= e(t('check-ins')) ?></li><?php endforeach; ?></ul><h2><?= e(t('Focus')) ?></h2><ul><?php foreach($report['focus'] as $day): ?><li><?= e($day['day']) ?> · <?= (int)$day['minutes'] ?> <?= e(t('minutes')) ?></li><?php endforeach; ?></ul><p><a href="/profiles"><?= e(t('Back')) ?></a></p>
